def _sha256_csp(text):
    return "sha256-" + base64.b64encode(hashlib.sha256(text.encode()).digest()).decode()


def render_dashboard(report):
    """Recompute measurements before rendering; embed inert, escaped JSON."""
    report = validate_projection(report)
    view = {key: value for key, value in report.items() if key != "snapshot"}
    view["report_sha256"] = digest(report)
    raw = json.dumps(view, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    for old, new in (("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"), ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        raw = raw.replace(old, new)
    csp = ("default-src 'none'; connect-src 'none'; object-src 'none'; base-uri 'none'; "
           "form-action 'none'; frame-src 'none'; img-src 'none'; font-src 'none'; "
           "script-src '" + _sha256_csp(_SCRIPT) + "'; style-src '" + _sha256_csp(_STYLE) + "'")
    prefix = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    prefix += '<meta http-equiv="Content-Security-Policy" content="' + html.escape(csp, quote=True) + '">'
    prefix += '<meta name="referrer" content="no-referrer"><title>Keel · Private review desk</title><style>' + _STYLE + '</style></head>'
    body = r"""<body><a class="skip" href="#main">Skip to review desk</a><div class="shell"><aside class="rail" aria-label="Workspace"><div class="brand"><span class="brandmark" aria-hidden="true">K</span>KEEL</div><div><p class="rail-label">Application workspace</p><div class="rail-current"><span class="rail-dot" aria-hidden="true"></span>Review desk</div><p class="rail-note">A clear view of the facts,<br>the changes, and your<br>next decision.</p></div><div class="rail-bottom">Your decisions stay yours.<br><span class="small">Private snapshot · no live connection</span></div></aside><main id="main" class="workspace"><div class="topbar"><p class="crumb">Workspace / Applications / Review</p><span class="pill"><span class="dot" aria-hidden="true"></span>Local review file</span></div><div class="intro"><div><p class="eyebrow">Human review</p><h1>A little clarity. Your next step.</h1><p>Review the exact questions, inspect the evidence, and see what changed before you decide.</p></div><div class="snapshot"><p id="snapshot-date"></p><p id="snapshot-age"></p></div></div><div class="notice"><span aria-hidden="true">↗</span><p><strong>This desk exports review requests.</strong> Nothing is sent, submitted or approved here. Your authenticated Keel host checks the current records and captures your decision.</p></div><section id="metrics" class="metrics" aria-label="Queue measurements"></section><div class="main-grid"><div><section class="panel" aria-labelledby="queue-title"><div class="panel-head"><h2 id="queue-title">Your queue</h2><span id="queue-count" class="count" aria-live="polite"></span></div><div class="controls"><div><label class="screen-reader" for="search">Search roles, employers or blockers</label><input id="search" type="search" placeholder="Search roles or employers" autocomplete="off"></div><div><label class="screen-reader" for="status-filter">Filter by status</label><select id="status-filter"><option value="all">All statuses</option><option value="NEEDS_REVIEW">Needs review</option><option value="BLOCKED">Blocked</option><option value="PACKET_CHANGED">Packet changed</option><option value="PREPARED">Prepared</option><option value="SUBMISSION_OBSERVED">Receipt observed</option></select></div></div><ul id="queue" class="queue"></ul></section><section class="panel breakdown" aria-labelledby="causes-title"><h3 id="causes-title">Where work is waiting</h3><div id="causes"></div></section><section id="measurements" class="mini-metrics" aria-label="Observed operational measurements"></section></div><section class="panel" aria-label="Selected application"><div id="detail-head" class="detail-head"></div><div class="tabs" role="tablist" aria-label="Application details"><button id="tab-review" class="tab" type="button" role="tab" data-tab="review" aria-selected="true" aria-controls="detail-body">Your review</button><button id="tab-packet" class="tab" type="button" role="tab" data-tab="packet" aria-selected="false" aria-controls="detail-body" tabindex="-1">Packet &amp; changes</button><button id="tab-evidence" class="tab" type="button" role="tab" data-tab="evidence" aria-selected="false" aria-controls="detail-body" tabindex="-1">Evidence</button><button id="tab-timeline" class="tab" type="button" role="tab" data-tab="timeline" aria-selected="false" aria-controls="detail-body" tabindex="-1">Timeline</button></div><div id="detail-body" class="detail-body" role="tabpanel" aria-labelledby="tab-review"></div></section></div><footer class="footer"><span>Keel · A grounded application workspace</span><span>Unknown measurements stay unknown. Source observations are not authenticated by this file.</span></footer><noscript><p class="notice">JavaScript is required for the local review interface. No network connection is used.</p></noscript></main></div><div id="message" class="live-message" role="status" aria-live="polite"></div>"""
    return prefix + body + '<script id="review-data" type="application/json">' + raw + '</script><script>' + _SCRIPT + '</script></body></html>'


def write_dashboard(path, report):
    """Atomically publish one private HTML file without overwriting anything."""
    from tools.bench_inventory import directory_fd, safe_name
    raw = render_dashboard(report).encode()
    path = Path(path).absolute()
    safe_name(path.name)
    parent = directory_fd(path.parent)
    temporary = ".keel-review-" + secrets.token_hex(16)
    temporary_path = Path("/proc/self/fd") / str(parent) / temporary
    identity = None
    try:
        fd = os.open(temporary_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        identity = os.fstat(fd)
        with os.fdopen(fd, "wb") as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
            identity = os.fstat(stream.fileno())
            os.link("/proc/self/fd/" + str(stream.fileno()), Path("/proc/self/fd") / str(parent) / path.name,
                    dst_dir_fd=parent, follow_symlinks=True)
            os.fsync(parent)
    finally:
        try:
            current = os.stat(temporary, dir_fd=parent, follow_symlinks=False)
            if identity is not None and (current.st_dev, current.st_ino) == (identity.st_dev, identity.st_ino):
                temporary_path.unlink()
        except FileNotFoundError:
            pass
        os.close(parent)
    return {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw),
            "execution_authorized": False, "network_requests": 0}


def demo(home):
    """Write a synthetic private fixture to an existing directory, no browser."""
    home = Path(home).absolute()
    for name in ("review.html", "review-summary.json"):
        if (home / name).exists() or (home / name).is_symlink():
            raise FileExistsError("demo output already exists")
    snapshot = example_snapshot()
    report = project_review(snapshot, now=snapshot["captured_at"])
    output = write_dashboard(home / "review.html", report)
    summary = {"schema": "keel.muse.review-demo.v1", "synthetic": True, "dashboard": output,
        "snapshot_sha256": report["snapshot_sha256"], "report_sha256": digest(report), "metrics": report["metrics"],
        "browser_render_verified": False, "execution_authorized": False, "network_requests": 0,
        "scope": "Generated standalone HTML; functional browser validation must be reported separately."}
    atomic_json(home / "review-summary.json", summary)
    return summary
